/* Approved AI news C cover integration only */
(()=>{function showCover(){const root=document.querySelector("#ai-news-daily");if(!root)return;
  // Keep the approved cover independent of the daily feed and its loading state.
  if(!root.parentElement.querySelector('[data-ai-news-cover]')){
    const cover=document.createElement('figure')
    cover.dataset.aiNewsCover='c'
    cover.style.cssText='margin:0 0 32px;width:100%;min-width:0;'
    const link=document.createElement('a')
    link.href='/images/ai-news-cover-c.png'
    link.target='_blank'
    link.rel='noopener'
    link.setAttribute('aria-label','查看洋洋子AI资讯C版封面原图')
    const image=document.createElement('img')
    image.src=link.href
    image.alt='洋洋子AI资讯封面 AI越来越会干活 我该怎么学 从收藏教程到做出作品'
    image.width=1080
    image.height=1440
    image.decoding='async'
    image.style.cssText='display:block;width:100%;max-width:360px;height:auto;margin:0 auto;'
    link.append(image)
    cover.append(link)
    root.prepend(cover)
    // The feed below replaces root contents; preserve the cover as a preceding sibling
    // inside the same existing grid item instead of creating another grid column.
    const container=document.createElement('div')
    container.style.cssText='min-width:0;width:100%;max-width:100%;'
    root.before(container)
    container.append(cover,root)
  }
}
document.addEventListener("page:content",showCover);document.addEventListener("DOMContentLoaded",showCover,{once:true});queueMicrotask(showCover);})();
